            final int[] scratch = new int[n];
            final int[] count = new int[n];

            long sum = 0;
            int max = 0;

            for (;;) {
                long start = nextChunk.getAndAdd(CHUNK_SIZE);
                if (start >= total) {
                    break;
                }
                long end = Math.min(start + CHUNK_SIZE, total);

                // Decode the starting index in the required permutation order.
                for (int i = 0; i < n; ++i) {
                    permutation[i] = i;
                    count[i] = 0;
                }

                long index = start;
                for (int i = n - 1; i > 0; --i) {
                    int rotation = (int) (index / factorial[i]);
                    index %= factorial[i];
                    count[i] = rotation;

                    if (rotation != 0) {
                        int length = i + 1;
                        System.arraycopy(permutation, 0, scratch, 0, length);
                        int source = rotation;
                        for (int j = 0; j < length; ++j) {
                            permutation[j] = scratch[source];
                            if (++source == length) {
                                source = 0;
                            }
                        }
                    }
                }

                for (long position = start; position < end; ++position) {
                    int first = permutation[0];
                    if (first != 0) {
                        int flips = 1;

                        if (permutation[first] != 0) {
                            System.arraycopy(permutation, 0, scratch, 0, n);

                            // Keep the first element in a register. The last
                            // flip need not be performed once it exposes zero.
                            int next;
                            while ((next = scratch[first]) != 0) {
                                for (int left = 1, right = first - 1;
                                     left < right; ++left, --right) {
                                    int value = scratch[left];
                                    scratch[left] = scratch[right];
                                    scratch[right] = value;
                                }
                                scratch[first] = first;
                                first = next;
                                ++flips;
                            }
                        }

                        if (flips > max) {
                            max = flips;
                        }
                        sum += ((position & 1L) == 0) ? flips : -flips;
                    }

                    if (position + 1 == end) {
                        break;
                    }

                    // Advance the mixed-radix permutation counter.
                    int value = permutation[0];
                    permutation[0] = permutation[1];
                    permutation[1] = value;

