import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class spectralnorm {
    private static void multiplyRows(
            double[] source, double[] destination,
            int start, int end, boolean transpose) {

        int n = source.length;
        int limit = n - (n % 4);

        for (int i = start; i < end; i++) {
            int denominator = i * (i + 1) / 2 + (transpose ? 1 : i + 1);
            int increment = i + (transpose ? 2 : 1);

            double sum0 = 0.0;
            double sum1 = 0.0;
            double sum2 = 0.0;
            double sum3 = 0.0;

            int j = 0;
            for (; j < limit; j += 4) {
                sum0 += source[j] / denominator;
                denominator += increment++;

                sum1 += source[j + 1] / denominator;
                denominator += increment++;

                sum2 += source[j + 2] / denominator;
                denominator += increment++;

                sum3 += source[j + 3] / denominator;
                denominator += increment++;
            }

            double sum = (sum0 + sum1) + (sum2 + sum3);
            for (; j < n; j++) {
                sum += source[j] / denominator;
                denominator += increment++;
            }
            destination[i] = sum;
        }
    }

    private static void multiply(
            double[] source, double[] destination, boolean transpose,
            ExecutorService executor, int workers) throws Exception {

        if (executor == null) {
            multiplyRows(source, destination, 0, source.length, transpose);
            return;
        }

        Future<?>[] futures = new Future<?>[workers];
        for (int worker = 0; worker < workers; worker++) {
            final int start = source.length * worker / workers;
            final int end = source.length * (worker + 1) / workers;
            futures[worker] = executor.submit(
                    () -> multiplyRows(source, destination, start, end, transpose));
        }

        for (Future<?> future : futures) {
            future.get();
        }
    }

    private static void multiplyAtA(
            double[] source, double[] destination, double[] temporary,
            ExecutorService executor, int workers) throws Exception {
        multiply(source, temporary, false, executor, workers);
        multiply(temporary, destination, true, executor, workers);
    }

    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);

        double[] u = new double[n];
        double[] v = new double[n];
        double[] temporary = new double[n];
        Arrays.fill(u, 1.0);

        int workers = Math.min(
                Math.min(Runtime.getRuntime().availableProcessors(), 16),
                Math.max(1, n / 64));

        ExecutorService executor =
                workers > 1 ? Executors.newFixedThreadPool(workers) : null;

